typedef struct CustomStreamInfo {
    unsigned int signature;
} CustomStreamInfo;

typedef struct BlobInfo {
    void *blob_data;
    int is_mapped;
} BlobInfo;

// Function to log an event; assumed to be defined elsewhere.
void LogEvent(const char *message);

// Function to unmap a blob; assumed to be defined elsewhere.
void UnmapBlob(void **blob_ptr);

CustomStreamInfo *DestroyCustomStreamInfo(CustomStreamInfo *custom_stream) {
    if (custom_stream == NULL) {
        return NULL;
    }

    LogEvent("Destroying CustomStreamInfo");

    if (custom_stream->signature != 0xDEADBEEF) {
        return custom_stream;  // Invalid signature
    }

    custom_stream->signature = 0;  // Mark as invalid
    free(custom_stream);
    return NULL;
}

void *DetachBlob(BlobInfo *blob_info) {
    assert(blob_info != NULL);

    LogEvent("Detaching blob");

    if (blob_info->is_mapped) {
        UnmapBlob(&blob_info->blob_data);
    }

    void *detached_blob = blob_info->blob_data;
    blob_info->blob_data = NULL;
    return detached_blob;
}
